const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$tests=@(
 'https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=college&query=tutor&limit=25&after=2024-06-01',
 'https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=college&query=tutor&limit=25&after=2025-01-01',
 'https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=college&query=essay&limit=25&after=2025-01-01',
 'https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=college&limit=25&after=2025-06-01'
)
foreach($u in $tests){
  $code = curl.exe -s -o "$env:TEMP\\a4.json" -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 60 --compressed $u
  $c = Get-Content "$env:TEMP\\a4.json" -Raw -ErrorAction SilentlyContinue
  Write-Output "== $code  $u"
  if($c -and $c.Length -lt 300){ Write-Output "   $c" }
  Start-Sleep -Seconds 13
}
`;
const r = await tools.pwsh({ description: "Probe ArcticShift with date filters", command: cmd, timeoutMs: 300000 });
console.log(r.kind === 'foreground' ? r.stdout.text + "|ERR:" + r.stderr.text : JSON.stringify(r));
